/* ==UserStyle==
@name         修正中文引号样式 - 霞鹜文楷等宽 (包括输入框)
@version      2.1
@description  修正中文引号（‘ ’ “ ”）显示为“霞鹜文楷等宽”，特别处理输入框(input, textarea)以确保生效。请确保已安装字体！
@author       (你的名字) 
==/UserStyle== */

/* 
  专门为中文引号定义字体规则 (保持不变)
*/
@font-face {
  font-family: 'Fix Chinese Quotes Font'; 
  src: local("LXGW WenKai Mono"), 
       local("霞鹜文楷等宽");      
  unicode-range: U+2018, U+2019, U+201C, U+201D; 
  font-weight: normal;
  font-style: normal;
}

/*
  显式为 input 和 textarea 元素设置字体规则 (保持不变)
*/
input, 
textarea {
  font-family: 'Fix Chinese Quotes Font', /* 强制检查引号修正 */
               "LXGW WenKai Mono",      /* 输入框其他字符使用此字体 */
               "霞鹜文楷等宽",          /* 中文名备选 */
               system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif,
               monospace             
               !important; 
}

/*
  说明：
  此版本为适应 Stylish 发布系统，大幅简化了 UserStyle 元数据块，
  移除了 @namespace, @match, @grant 等可能导致其验证器报错的指令。
  核心的 @font-face 和 input/textarea 样式规则保持不变。
  理论上，Stylish 发布系统应该能识别这个简化的元数据块，并接受其中的 CSS 规则。
*/
